const filter = (typeof entityFilter === 'string') ? entityFilter : 'animal';
const p = drone.getPlayer();
const found = drone.getEntities({ radius: 8, filter: filter });
if (!found || !found.entities || !found.entities.length) return { ok: false, error: 'no matching entity nearby', filter: filter };
const id = found.entities[0].id;
const picked = drone.pickEntity({ entity_id: id });
if (!picked || picked.ok === false || picked.picked !== true) return picked;
const dest = (typeof destination === 'object' && destination !== null)
  ? destination
  : { x: p.blockX + 4, y: p.blockY + 2, z: p.blockZ };
const moved = drone.goto({ x: dest.x, y: dest.y, z: dest.z });
if (!moved || moved.ok === false || moved.arrived !== true) {
  drone.unpickEntity({ entity_id: id });
  return { ok: false, error: 'could not fly to destination', moved: moved };
}
return drone.unpickEntity({ entity_id: id });
